INSERT INTO recipe_ingredients (recipe_id, ingredient_name, ingredient_amount) VALUES (5, '애느타리버섯', '20g(4가닥)');
INSERT INTO recipe_ingredients (recipe_id, ingredient_name, ingredient_amount) VALUES (5, '감자', '10g(4×3×1cm)');
