INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (13, '오렌지는 깨끗이 씻어 껍질을 벗긴다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (13, '당근은 깨끗이 씻어 작은 토막으로 썬다.');
