INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (33, '훈제오리 가슴살을 슬라이스한다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (33, '슬라이스한 훈제오리는 팬에 굽는다.');
