VALUES (40, 1, '백김치콩비지찌개', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00273_1.png', '끓이기', '염증감소', '한식', '보통', 0, 0, '콩비지찌개를 끓일 때 넣는 묵은지 대신
