VALUES (41, 1, '오징어김치찌개', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00274_1.png', '끓이기', '염증감소', '한식', '보통', 0, 0, '김치의 속을 덜어내 염분을 줄였고,
