VALUES (48, 1, '백태순두부찌개', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00281_1.png', '끓이기', '염증감소', '한식', '보통', 0, 0, '매콤한 보통의 순두부찌개와는 달리 백태와 청양고추로
